from .core import (CONTENT, SITE, UPDATED, breadcrumb, build_challenge, faq, learning_schema, lesson_header, page, quick_answer, takeaways)


def build():
    slug='token-playground';d=CONTENT['lessons'][slug]
    token_body=f'''<div class="container">{lesson_header(slug,'◇')}{quick_answer(d['quick'])}<div class="lesson-grid"><div><section class="card interactive"><div style="display:grid;grid-template-columns:1fr 1.3fr;gap:28px"><div><div class="panel-title">1 · Prompt</div><div class="task-box" style="margin-top:10px">The capital of France is</div></div><div><div class="panel-title">2 · Tokenization</div><div style="margin-top:10px"><span class="badge">The</span> <span class="badge">capital</span> <span class="badge">of</span> <span class="badge">France</span> <span class="badge">is</span></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><div style="display:grid;grid-template-columns:1.1fr 1fr;gap:28px"><div><div class="panel-title">3 · Next-token probabilities</div><div class="prob-row" data-prob-row><span data-label>Paris</span><div class="bar"><span style="width:91%"></span></div><b data-value>0.91</b></div><div class="prob-row" data-prob-row><span data-label>Lyon</span><div class="bar light"><span style="width:3%"></span></div><b data-value>0.03</b></div><div class="prob-row" data-prob-row><span data-label>located</span><div class="bar light"><span style="width:2%"></span></div><b data-value>0.02</b></div></div><div><div class="panel-title">4 · Temperature</div><div class="temp-row" style="margin:15px 0"><input id="temperature" class="slider" type="range" min="0" max="2" value="0.7" step="0.05" aria-label="Temperature"><output id="temperature-value" class="badge">0.70</output></div><div class="selected-panel"><span class="subtle">5 · Example sampled token</span><div class="big" data-selected-token>Paris</div><span>Probability: <b data-selected-prob>0.91</b></span></div></div></div></section>{takeaways([('Tokens are building blocks','Models read and write token units.'),('Probabilities guide choices','Candidate tokens receive different scores.'),('Temperature changes randomness','Higher values flatten the distribution.'),('Generation is iterative','The chosen token becomes new context.')])}{build_challenge('Choose decoding settings for structured output','Would you use the same temperature for creative copy and strict JSON? Explain the trade-off before opening the next lab.')}</div><aside class="lesson-sidebar"><div class="card side-card"><h3>What you’ll learn</h3><ul class="check-list"><li>How text becomes tokens</li><li>How next-token probabilities work</li><li>How temperature changes sampling</li></ul></div><div class="card side-card"><h3>Lesson path</h3><ol class="steps"><li class="done"><span class="step-num">1</span><div><b>Prompt</b><div class="subtle">Read the input</div></div><span>✓</span></li><li class="done"><span class="step-num">2</span><div><b>Tokenize</b><div class="subtle">Split text units</div></div><span>✓</span></li><li class="active"><span class="step-num">3</span><div><b>Predict</b><div class="subtle">Inspect probabilities</div></div></li><li><span class="step-num">4</span><div><b>Sample</b><div class="subtle">Change temperature</div></div></li><li><span class="step-num">5</span><div><b>Repeat</b><div class="subtle">Append next token</div></div></li></ol></div></aside></div><section class="card section-explainer"><span class="eyebrow">Concept guide</span><h2>How does next-token prediction work?</h2><p>A large language model generates text by estimating a probability distribution over possible next tokens, selecting a token using a decoding strategy, adding the selected token to the current context, and repeating the process.</p><h3>What is a token?</h3><p>A token is a text unit used by the model. It can be a whole word, part of a word, punctuation, whitespace, or another fragment depending on the tokenizer.</p><h3>What does temperature change?</h3><p>Temperature changes the shape of the sampling distribution. Lower values concentrate probability around top candidates; higher values give lower-ranked candidates more chance to appear.</p><h3>Why does this matter in engineering?</h3><p>Decoding choices affect variability, deterministic behavior, structured-output reliability, and how an application balances creativity with control.</p><h3>Common questions</h3>{faq([('Does an LLM choose a whole sentence at once?','No. Autoregressive language models generate incrementally, token by token.'),('Is a token always a word?','No. Token boundaries depend on the tokenizer and can split words or include punctuation.'),('Does temperature change model knowledge?','No. It changes sampling behavior, not the model weights or underlying knowledge.'),('Are the probabilities in this lab from a live model?','No. This MVP uses deterministic educational values so the learning experience stays stable.')])}<div class="references"><strong>SeeAI learning note</strong> · Reviewed {UPDATED}. Interactive values are illustrative; conceptual explanations are the durable learning content.</div></section><section class="card next-band"><div><strong>Token prediction makes sense now.</strong><div class="subtle">Next: understand the finite working context around those tokens.</div></div><a class="btn primary" data-event="lesson_next_clicked" href="/en/lessons/context-window/">Continue →</a></section></div>'''
    (SITE/f'en/lessons/{slug}/index.html').write_text(page(f"{d['name']} — How LLM next-token prediction works | SeeAI",d['description'],f'/en/lessons/{slug}/',token_body,active='Lessons',schemas=[learning_schema(slug),breadcrumb([('SeeAI','/en/'),('Lessons','/en/#lessons'),(d['name'],f'/en/lessons/{slug}/')])],scripts='<script src="/assets/token.js" defer></script>'),encoding='utf-8')
